mapper.select:
SELECT tpd.*, fp.FINPROD_MARKET_ID, fp.FINPROD_NAME, fpt.TYPE_6,
fpt.TYPE_9, fpt.TYPE_10, fpt.TYPE_11
FROM (
SELECT T1.TRADE_ID, #{VALID_STATUS_01} VALID_STATUS, T1.FINPROD_TYPE2, T1.FINPROD_ID, T1.PS, T1.TRADE_MARKET, T1.TRADE_PLAT, T1.TRADE_MARKET_MODE,T1.TRADE_AMT, T1.PRIN_AMT,T1.SHARE_AMT, T1.CCY, T1.TRADE_DATE, T1.SETTLE_DATE, T1.REMARK,T1.WORKFLOW_ID, null WORKFLOW_STATUS,T1.B_TRADE_ID,T2.ENTRUST_ID,T2.PORTFOLIO_ID,pp.PORTFOLIO_NAME,pp.PARENT_PORTFOLIO_ID, T1.TOTLE_TRADE_ID FROM (SELECT * FROM WFL_TRD_PRODUCT_DEAL MINUS SELECT W1.* FROM WFL_TRD_PRODUCT_DEAL W1 INNER JOIN WFL_TRD_PRODUCT_DEAL W2 ON W1.B_TRADE_ID = W2.TRADE_ID WHERE W1.PS = #{PS24}) T1 LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD T2 ON T1.TRADE_ID = T2.TRADE_ID LEFT JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = T2.PORTFOLIO_ID
(T1.IS_CANCEL is null or T1.IS_CANCEL = #{YES_NO_NO}) and T1.TRADE_STATUS = #{TRADESTATUS_NEW}
UNION ALL SELECT T1.TRADE_ID, #{VALID_STATUS_02} VALID_STATUS, T1.FINPROD_TYPE2, T1.FINPROD_ID, T1.PS, T1.TRADE_MARKET, T1.TRADE_PLAT, T1.TRADE_MARKET_MODE,T1.TRADE_AMT, T1.PRIN_AMT,T1.SHARE_AMT, T1.CCY, T1.TRADE_DATE, T1.SETTLE_DATE, T1.REMARK, null WORKFLOW_ID, null WORKFLOW_STATUS,T1.B_TRADE_ID,T2.ENTRUST_ID,pp.PORTFOLIO_ID,pp.PORTFOLIO_NAME,pp.PARENT_PORTFOLIO_ID, T1.TOTLE_TRADE_ID FROM TRD_PRODUCT_DEAL T1 LEFT JOIN TRD_PRODUCT_DEAL_ADD T2 ON T1.TRADE_ID = T2.TRADE_ID LEFT JOIN PTL_TRADE PT ON T1.TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID
PP.INVEST_YESORNO = 'Y' AND (T1.IS_CANCEL is null or T1.IS_CANCEL = #{YES_NO_NO}) and T1.TRADE_STATUS = #{TRADESTATUS_NEW}
UNION ALL SELECT T1.TRADE_ID, #{VALID_STATUS_03} VALID_STATUS, T1.FINPROD_TYPE2, T1.FINPROD_ID, T1.PS, T1.TRADE_MARKET, T1.TRADE_PLAT, T1.TRADE_MARKET_MODE,T1.TRADE_AMT, T1.PRIN_AMT,T1.SHARE_AMT, T1.CCY, T1.TRADE_DATE, T1.SETTLE_DATE, T1.REMARK, null WORKFLOW_ID, null WORKFLOW_STATUS,T1.B_TRADE_ID,T2.ENTRUST_ID,pp.PORTFOLIO_ID,pp.PORTFOLIO_NAME,pp.PARENT_PORTFOLIO_ID, T1.TOTLE_TRADE_ID FROM TRD_PRODUCT_DEAL T1 LEFT JOIN TRD_PRODUCT_DEAL_ADD T2 ON T1.TRADE_ID = T2.TRADE_ID LEFT JOIN PTL_TRADE PT ON T1.P_TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID
PP.INVEST_YESORNO = 'Y' AND T1.TRADE_STATUS = #{TRADESTATUS_REVOKE}
) tpd LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = tpd.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = fp.FINPROD_ID
fp.FINPROD_TYPE2 = #{COMMON_BUSINESS_TYPE_TRD02} AND fp.PROFIT_TYPE= #{PROFIT_TYPE}
AND (tpd.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUser}) OR tpd.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUser}))
AND (TPD.PORTFOLIO_ID IN (#{item} ) OR TPD.PARENT_PORTFOLIO_ID IN (#{item}))
AND tpd.ENTRUST_ID like CONCAT_WS('', #{entrustId}, '%')
AND fp.FINPROD_MARKET_ID like CONCAT_WS('', #{finprodId}, '%')
AND fpt.TYPE_6 = #{type6}
#{type9,jdbcType=VARCHAR}
#{type10,jdbcType=VARCHAR}
#{type11,jdbcType=VARCHAR}
AND tpd.PS in
#{item}
AND tpd.TRADE_DATE >= STR_TO_DATE(#{tradeDateBegin}, '%Y-%m-%d')
AND tpd.TRADE_DATE <= STR_TO_DATE(#{tradeDateEnd}, '%Y-%m-%d')
ORDER BY tpd.TRADE_DATE DESC

SELECT T1.FINPROD_ID id, T1.FINPROD_NAME text, T1.FINPROD_NAME, T1.CCY, T1.CALENDAR_ID, DATE_FORMAT(T1.VDATE, '%Y-%m-%d') VDATE, T1.ISSUER, T2.TYPE_6,
T2.TYPE_9, T2.TYPE_10, T2.TYPE_11,
T2.TYPE_7, T1.MANAGER FROM FIN_PRODUCT T1 LEFT JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID
(T1.FINPROD_MARKET_ID LIKE CONCAT_WS('', '%', #{search}, '%') or T1.FINPROD_NAME LIKE CONCAT_WS('', '%', #{search}, '%'))
AND T1.FINPROD_ID = #{initValue}
AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG}
AND T1.PROFIT_TYPE = #{PROFIT_TYPE}

SELECT tpd.SETTLE_SPEED, tpd.TRADE_ID, tpd.FINPROD_TYPE2, tpda.ENTRUST_ID, tpda.RED_CFM_DATE, PP.PORTFOLIO_ID, tpd.SETTLE_SPEED, tpd.TRADE_DATE, tpd.SETTLE_DATE, tpd.PS, tpd.FINPROD_ID, fp.FINPROD_NAME, tpd.TRADE_MARKET, tpd.TRADE_PLAT, tpd.TRADE_MARKET_MODE,
tpd.FEE_AMT_PAY - ttfd.FEE_AMT channelFee, ttfd.FEE_AMT FEE_AMT_PAY,
tpd.INV_AIM, tpd.F_TRADE_ID, tpd.SEC_MANAGE_ACCT_ID, tpd.CCY, tpd.TRADE_AMT, tpd.PRIN_AMT, tpd.SHARE_AMT, tpd.UNIT_CPRICE, tpd.UNIT_INT, tpd.UNIT_FPRICE, tpd.CPRICE_DATE, tpd.CPRICE_AMT, tpd.B_TRADE_ID, tpd.P_TRADE_ID, tpd.INT_AMT, tpd.FPRICE_AMT, tpd.YIELD, tpd.EXER_YIELD, tpd.REMARK, tpd.TRADER, tpd.COUNTER_ID, tpd.COUNTER_TRADER, tpd.COUNTER_CONTACT FROM TRD_PRODUCT_DEAL tpd LEFT JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpda.TRADE_ID = tpd.TRADE_ID LEFT JOIN PA_TRD_PRODUCT_DEAL ptpd ON ptpd.TRADE_ID = tpd.TRADE_ID LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = tpd.FINPROD_ID
LEFT JOIN TRD_TRADE_FEE_DETAIL TTFD ON TPD.TRADE_ID = TTFD.TRADE_ID and ttfd.FEE_TYPE = #{feeType}
LEFT JOIN PTL_TRADE PT ON IFNULL(tpd.P_TRADE_ID,tpd.TRADE_ID) = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID WHERE PP.INVEST_YESORNO = 'Y' AND tpd.TRADE_ID = #{tradId}

SELECT IFNULL(T1.ENTRUST_AMT,T1.ENTRUST_NUM) entrustAmt, IFNULL(T2.FINISH_AMT,0) finishAmt, IFNULL(IFNULL(T5.PRIN_AMT,T5.SHARE_AMT),0) prinAmt FROM ETR_ENTRUST T1 LEFT JOIN ( SELECT FINISH_AMT, ENTRUST_ID FROM ETR_FINISH_STATUS
ENTRUST_ID = #{entrustId}
) T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN ( SELECT T4.PRIN_AMT,T3.ENTRUST_ID,T4.SHARE_AMT FROM WFL_TRD_PRODUCT_DEAL_ADD T3 LEFT JOIN WFL_TRD_PRODUCT_DEAL T4 ON T3.TRADE_ID = T4.TRADE_ID
T3.ENTRUST_ID = #{entrustId} AND T4.PS IN (#{pssg},#{pssh})
AND T4.TRADE_ID <> #{tradeId}
) T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID
T1.ENTRUST_ID = #{entrustId}
